INSERT INTO news_translations (news_translation_id, news_id, language_code, title, slug, summary, seo_title, seo_description, created_at, updated_at) VALUES
  (1, 1, 'vi', 'Sinh viên hỗ trợ lễ ký kết Porto AI Hub', 'sinh-vien-ho-tro-le-ky-ket-porto-ai-hub', 'Bản nháp ghi lại vai trò student buddy trong lễ ký kết.', 'Sinh viên hỗ trợ lễ ký kết Porto AI Hub', 'Câu chuyện hậu trường về hoạt động student buddy tại FPTU Hà Nội.', '2026-06-02 08:30:00', NULL),
  (2, 2, 'vi', 'Theo dõi sau chuyến thăm SeoulTech AI Lab', 'theo-doi-sau-chuyen-tham-seoultech-ai-lab', 'Bài viết đang bị trả về để lược bỏ dữ liệu nội bộ.', 'SeoulTech AI Lab follow-up', 'Thông tin follow-up sau chuyến thăm SeoulTech tại FPTU Hà Nội.', '2026-06-16 08:40:00', '2026-06-16 11:00:00'),
  (3, 3, 'vi', 'FPTU Hà Nội và Porto AI Hub ký kết hợp tác seminar AI', 'fptu-ha-noi-porto-ai-hub-ky-ket-seminar-ai', 'Lễ ký kết mở ra chuỗi seminar AI ứng dụng trong quý tới.', 'FPTU và Porto AI Hub ký kết seminar AI', 'Tin tức hợp tác quốc tế về AI ứng dụng tại FPTU Hà Nội.', '2026-06-01 13:00:00', '2026-06-01 16:30:00'),
  (4, 3, 'en', 'FPTU Hanoi and Porto AI Hub sign applied AI seminar plan', 'fptu-hanoi-porto-ai-hub-applied-ai-seminar-plan', 'The signing ceremony sets up a focused seminar series for applied AI.', 'FPTU Hanoi Porto AI Hub applied AI seminar', 'International partnership news about applied AI seminars at FPTU Hanoi.', '2026-06-01 13:10:00', '2026-06-01 16:30:00'),
  (5, 4, 'vi', 'Khoảnh khắc campus TP.HCM trong tour liên cơ sở', 'khoanh-khac-campus-hcm-tour-lien-co-so', 'Bài đã bị ẩn để chờ xác nhận quyền sử dụng hình ảnh.', 'Tour liên cơ sở tại FPTU TP.HCM', 'Hình ảnh hoạt động liên cơ sở tại FPTU TP.HCM.', '2026-05-26 08:30:00', '2026-06-01 10:00:00');

INSERT INTO news_content_sections (section_id, news_translation_id, section_order, section_title, section_body_html, section_body_text, created_at, updated_at) VALUES
  (1, 3, 1, 'Lễ ký kết tại Auditorium A', '<p>Đại diện FPTU Hà Nội và Porto AI Hub thống nhất chuỗi seminar AI ứng dụng cho sinh viên.</p>', 'Đại diện FPTU Hà Nội và Porto AI Hub thống nhất chuỗi seminar AI ứng dụng cho sinh viên.', '2026-06-01 13:10:00', '2026-06-01 16:30:00'),
  (2, 3, 2, 'Các đầu việc sau sự kiện', '<p>Hai bên sẽ hoàn thiện lịch speaker, tài liệu giới thiệu và kênh trao đổi học thuật trong tháng 6.</p>', 'Hai bên sẽ hoàn thiện lịch speaker, tài liệu giới thiệu và kênh trao đổi học thuật trong tháng 6.', '2026-06-01 13:20:00', '2026-06-01 16:30:00'),
  (3, 4, 1, 'Signing ceremony in Hanoi', '<p>FPTU Hanoi and Porto AI Hub agreed on a compact applied AI seminar roadmap.</p>', 'FPTU Hanoi and Porto AI Hub agreed on a compact applied AI seminar roadmap.', '2026-06-01 13:30:00', '2026-06-01 16:30:00'),
  (4, 1, 1, 'Vai trò student buddy', '<p>Student buddy hỗ trợ check-in, điều phối ảnh và chuẩn bị góc giao lưu.</p>', 'Student buddy hỗ trợ check-in, điều phối ảnh và chuẩn bị góc giao lưu.', '2026-06-02 08:40:00', NULL),
  (5, 5, 1, 'Tour campus HCM', '<p>Đoàn khách trải nghiệm tuyến đường xanh và khu học tập mở tại campus TP.HCM.</p>', 'Đoàn khách trải nghiệm tuyến đường xanh và khu học tập mở tại campus TP.HCM.', '2026-05-26 08:40:00', '2026-06-01 10:00:00');

