INSERT INTO visit_requests (visit_request_id, request_code, visitor_user_id, partner_id, created_source, registrant_full_name, registrant_organization, registrant_job_title, registrant_phone, registrant_email, registrant_nationality, delegation_name, visit_scope, visit_type, visit_type_other, purpose, working_content, contact_person_full_name, contact_person_organization, contact_person_phone, contact_person_email, working_language, transportation_note, media_consent_status, media_consent_note, note_to_fptu, status, submitted_at, email_verified_at, cancelled_by, cancelled_at, cancellation_reason, row_version, created_at, created_by, updated_at, updated_by) VALUES
  (3001, 'VR2-SC-3001', 8, 101, 'VISITOR_SUBMITTED', 'External Visitor Main', 'Indian Institute of Technology Delhi International Office', 'Delegation Coordinator', '+84900003001', 'visitor@example.com', 'Hàn Quốc', 'AI curriculum benchmarking delegation — single pending approval campus 1', 'SINGLE_CAMPUS', 'CAMPUS_TOUR', NULL, 'Đánh giá khả năng trao đổi chương trình học, chuẩn đầu ra và cách tổ chức hỗ trợ sinh viên quốc tế.', 'Làm việc tại phòng họp chính, tham quan khu học tập, gặp đại diện IC và chốt đầu mối follow-up.', 'External Visitor Main', 'Indian Institute of Technology Delhi International Office', '+84901003001', 'visitor@example.com', 'VI', 'Khách tự túc phương tiện. Đoàn tự bố trí xe và gửi biển số trước giờ đến.', 'DECLINED', NULL, 'Seed coverage: single pending approval campus 1', 'PENDING_APPROVAL', '2026-07-01 08:00:00', '2026-07-01 08:03:00', NULL, NULL, NULL, 0, '2026-07-01 08:00:00', 8, NULL, NULL),
  (3002, 'VR2-SC-3002', 8, 102, 'VISITOR_SUBMITTED', 'External Visitor Main', 'Politecnico di Milano Mobility Lab', 'Delegation Coordinator', '+84900003002', 'visitor@example.com', 'Hàn Quốc', 'Green campus energy walk — single rejected by Staff Leader campus 1', 'SINGLE_CAMPUS', 'MEETING', NULL, 'Khảo sát cách campus vận hành không gian xanh, di chuyển nội khu và tiếp đón đoàn quy mô nhỏ.', 'Yêu cầu chuẩn bị route riêng cho đoàn, hạn chế di chuyển quá nhiều và ưu tiên minh họa trực quan.', 'External Visitor Main', 'Politecnico di Milano Mobility Lab', '+84901003002', 'visitor@example.com', 'EN', 'Khách đề nghị FPTU hỗ trợ phương tiện. Đề nghị FPTU hỗ trợ xe điện nội khu và hướng dẫn bãi đỗ.', 'AGREED', 'Đồng ý sử dụng ảnh nhóm sau khi host xác nhận.', 'Seed coverage: single rejected by Staff Leader campus 1', 'REJECTED', '2026-07-02 09:00:00', '2026-07-02 09:03:00', NULL, NULL, NULL, 1, '2026-07-02 09:00:00', 8, '2026-07-02 15:20:00', 3),
  (3003, 'VR2-SC-3003', 8, 103, 'VISITOR_SUBMITTED', 'External Visitor Main', 'University of Technology Sydney Student Exchange', 'Delegation Coordinator', '+84900003003', 'visitor@example.com', 'Hàn Quốc', 'Robotics classroom demonstration — single approved instance ASSIGNED campus 1', 'SINGLE_CAMPUS', 'WORKSHOP', NULL, 'Thử nghiệm mô hình demo công nghệ trước sinh viên và thu thập phản hồi để xây dựng workshop chính thức.', 'Cần host nắm rõ agenda, hỗ trợ phiên dịch nhẹ và ghi nhận câu hỏi sau từng hoạt động.', 'External Visitor Main', 'University of Technology Sydney Student Exchange', '+84901003003', 'visitor@example.com', 'EN', 'Visitor chưa chốt phương án di chuyển tại thời điểm gửi form.', 'AGREED', 'Đồng ý sử dụng ảnh nhóm sau khi host xác nhận.', 'Seed coverage: single approved instance ASSIGNED campus 1', 'APPROVED', '2026-07-03 10:00:00', '2026-07-03 10:03:00', NULL, NULL, NULL, 2, '2026-07-03 10:00:00', 8, '2026-07-03 16:20:00', 3),
  (3004, 'VR2-SC-3004', 8, 104, 'VISITOR_SUBMITTED', 'External Visitor Main', 'Nordic Green Campus Alliance', 'Delegation Coordinator', '+84900003004', 'visitor@example.com', 'Hàn Quốc', 'International credit transfer workshop — single approved instance BEFORE_VISIT campus 1', 'SINGLE_CAMPUS', 'SIGNING_CEREMONY', NULL, 'Làm việc với IC, phòng đào tạo và đại diện sinh viên để so sánh quy trình credit transfer.', 'Có phần trao đổi riêng với department support để kiểm thử task, logistics và feedback.', 'External Visitor Main', 'Nordic Green Campus Alliance', '+84901003004', 'visitor@example.com', 'EN', 'Phương tiện khác. Di chuyển kết hợp bus thuê riêng và xe điện nội bộ.', 'DECLINED', NULL, 'Seed coverage: single approved instance BEFORE_VISIT campus 1', 'APPROVED', '2026-07-04 11:00:00', '2026-07-04 11:03:00', NULL, NULL, NULL, 3, '2026-07-04 11:00:00', 8, '2026-07-04 17:20:00', 3),
  (3005, 'VR2-SC-3005', 8, 105, 'VISITOR_SUBMITTED', 'External Visitor Main', 'Paris Digital Arts Institute', 'Delegation Coordinator', '+84900003005', 'visitor@example.com', 'Hàn Quốc', 'Student entrepreneurship roundtable — single approved instance DURING_VISIT campus 1', 'SINGLE_CAMPUS', 'EXCHANGE', NULL, 'Tổ chức phiên hỏi đáp chuyên sâu về khởi nghiệp, đổi mới sáng tạo và mentoring xuyên campus.', 'Làm việc tại phòng họp chính, tham quan khu học tập, gặp đại diện IC và chốt đầu mối follow-up.', 'External Visitor Main', 'Paris Digital Arts Institute', '+84901003005', 'visitor@example.com', 'VI', 'Khách tự túc phương tiện. Đoàn tự bố trí xe và gửi biển số trước giờ đến.', 'AGREED', 'Đồng ý sử dụng ảnh nhóm sau khi host xác nhận.', 'Seed coverage: single approved instance DURING_VISIT campus 1', 'APPROVED', '2026-07-05 12:00:00', '2026-07-05 12:03:00', NULL, NULL, NULL, 4, '2026-07-05 12:00:00', 8, '2026-07-05 14:20:00', 3),
  (3006, 'VR2-SC-3006', 8, 106, 'VISITOR_SUBMITTED', 'External Visitor Main', 'Gulf Innovation Fund for Education', 'Delegation Coordinator', '+84900003006', 'visitor@example.com', 'Hàn Quốc', 'Hospitality and tourism showcase — single approved instance AFTER_VISIT campus 1', 'SINGLE_CAMPUS', 'OTHER', 'Special protocol rehearsal', 'Xem xét khả năng hợp tác hospitality, tourism management và mô hình học trải nghiệm tại cơ sở ven biển.', 'Yêu cầu chuẩn bị route riêng cho đoàn, hạn chế di chuyển quá nhiều và ưu tiên minh họa trực quan.', 'External Visitor Main', 'Gulf Innovation Fund for Education', '+84901003006', 'visitor@example.com', 'EN', 'Khách đề nghị FPTU hỗ trợ phương tiện. Đề nghị FPTU hỗ trợ xe điện nội khu và hướng dẫn bãi đỗ.', 'AGREED', 'Đồng ý sử dụng ảnh nhóm sau khi host xác nhận.', 'Seed coverage: single approved instance AFTER_VISIT campus 1', 'APPROVED', '2026-07-06 13:00:00', '2026-07-06 13:03:00', NULL, NULL, NULL, 5, '2026-07-06 13:00:00', 8, '2026-07-06 15:20:00', 3),
  (3007, 'VR2-SC-3007', 8, 107, 'VISITOR_SUBMITTED', 'External Visitor Main', 'Seattle EdTech Studio', 'Delegation Coordinator', '+84900003007', 'visitor@example.com', 'Hàn Quốc', 'Mekong community engagement visit — single approved instance CLOSED campus 1', 'SINGLE_CAMPUS', 'CAMPUS_TOUR', NULL, 'Đánh giá khả năng trao đổi chương trình học, chuẩn đầu ra và cách tổ chức hỗ trợ sinh viên quốc tế.', 'Cần host nắm rõ agenda, hỗ trợ phiên dịch nhẹ và ghi nhận câu hỏi sau từng hoạt động.', 'External Visitor Main', 'Seattle EdTech Studio', '+84901003007', 'visitor@example.com', 'EN', 'Visitor chưa chốt phương án di chuyển tại thời điểm gửi form.', 'DECLINED', NULL, 'Seed coverage: single approved instance CLOSED campus 1', 'APPROVED', '2026-07-07 14:00:00', '2026-07-07 14:03:00', NULL, NULL, NULL, 6, '2026-07-07 14:00:00', 8, '2026-07-07 16:20:00', 3),
