-- =====================================================================
-- PEMS v7 extension — Visitor cancellation + more records for non-HN accounts
-- Scope: adds explicit visitor self-cancel cases and more operational records
-- for HCM/DN/CT/QN Staff Leader, Staff, Department and Student accounts.
-- =====================================================================

INSERT INTO visit_requests (visit_request_id, request_code, visitor_user_id, partner_id, created_source, registrant_full_name, registrant_organization, registrant_job_title, registrant_phone, registrant_email, registrant_nationality, delegation_name, visit_scope, visit_type, visit_type_other, purpose, working_content, contact_person_full_name, contact_person_organization, contact_person_phone, contact_person_email, working_language, transportation_note, media_consent_status, media_consent_note, note_to_fptu, status, submitted_at, email_verified_at, cancelled_by, cancelled_at, cancellation_reason, row_version, created_at, created_by, updated_at, updated_by) VALUES
  (9001, 'VR7-SC-HCM-VISITOR-CANCEL-01', 202, 3, 'VISITOR_SUBMITTED', 'Sofia Bianchi', 'Politecnico di Milano Mobility Lab', 'International Partnership Officer', '+390210000202', 'sofia.bianchi@polimi.example', 'Ý', 'Milan mobility studio cancelled by visitor at HCM', 'SINGLE_CAMPUS', 'MEETING', NULL, 'Trao đổi về mobility studio, học kỳ trao đổi và khả năng tổ chức mini workshop cho sinh viên HCM.', 'Đoàn ban đầu cần phòng họp, campus walk và phiên làm việc với student service nhưng visitor đã chủ động hủy sau khi được duyệt.', 'Sofia Bianchi', 'Politecnico di Milano Mobility Lab', '+390210000202', 'sofia.bianchi@polimi.example', 'EN', 'Khách tự túc phương tiện. Đoàn tự bố trí xe từ trung tâm TP.HCM đến campus.', 'AGREED', 'Chỉ đồng ý dùng ảnh nhóm nếu chuyến đi diễn ra.', 'Case v7: visitor tự hủy toàn bộ request single-campus HCM sau khi Staff Leader đã duyệt.', 'CANCELLED', CURRENT_TIMESTAMP - INTERVAL 8 DAY, CURRENT_TIMESTAMP - INTERVAL 7 DAY - INTERVAL 23 HOUR - INTERVAL 57 MINUTE, 202, CURRENT_TIMESTAMP - INTERVAL 2 DAY - INTERVAL 4 HOUR, 'Visitor tự hủy trên portal vì đoàn đổi lịch bay và không còn đủ thời gian ở TP.HCM.', 5, CURRENT_TIMESTAMP - INTERVAL 8 DAY, 202, CURRENT_TIMESTAMP - INTERVAL 2 DAY - INTERVAL 4 HOUR, 202),
  (9002, 'VR7-SC-DN-VISITOR-CANCEL-02', 203, 2, 'VISITOR_SUBMITTED', 'Nguyen Kelly', 'University of Technology Sydney Student Exchange', 'Exchange Program Manager', '+61410000203', 'kelly.nguyen@uts.example', 'Úc', 'UTS robotics classroom visit cancelled by visitor at DN', 'SINGLE_CAMPUS', 'WORKSHOP', NULL, 'Chuẩn bị buổi demo robotics và trao đổi chương trình sinh viên tại Đà Nẵng.', 'Host và student robotics đã được mời, nhưng visitor báo hủy trước ngày đến vì giảng viên phụ trách bị ốm.', 'Nguyen Kelly', 'University of Technology Sydney Student Exchange', '+61410000203', 'kelly.nguyen@uts.example', 'EN', 'Khách đề nghị FPTU hỗ trợ phương tiện. Đề nghị campus hỗ trợ xe điện nội khu và bảng welcome.', 'DECLINED', NULL, 'Case v7: có host/participant/logistics nhưng visitor tự hủy trước chuyến.', 'CANCELLED', CURRENT_TIMESTAMP - INTERVAL 10 DAY - INTERVAL 2 HOUR, CURRENT_TIMESTAMP - INTERVAL 10 DAY - INTERVAL 1 HOUR - INTERVAL 57 MINUTE, 203, CURRENT_TIMESTAMP - INTERVAL 3 DAY - INTERVAL 2 HOUR, 'Visitor tự hủy do trưởng đoàn không thể bay sang Việt Nam theo kế hoạch.', 6, CURRENT_TIMESTAMP - INTERVAL 10 DAY - INTERVAL 2 HOUR, 203, CURRENT_TIMESTAMP - INTERVAL 3 DAY - INTERVAL 2 HOUR, 203),
  (9003, 'VR7-SC-CT-VISITOR-CANCEL-03', 210, 6, 'VISITOR_SUBMITTED', 'Priya Raman', 'Singapore Applied AI Consortium', 'Research Liaison', '+6590000210', 'priya.raman@singapore-ai.example', 'Singapore', 'Singapore AI curriculum visit cancelled by visitor at CT', 'SINGLE_CAMPUS', 'EXCHANGE', NULL, 'Trao đổi về AI curriculum và dự án sinh viên tại Cần Thơ.', 'Đoàn cần gặp IC, bộ phận event logistics và sinh viên Mekong, sau đó tự hủy vì đổi hướng hợp tác sang online.', 'Priya Raman', 'Singapore Applied AI Consortium', '+6590000210', 'priya.raman@singapore-ai.example', 'EN', 'Phương tiện khác. Đoàn dự kiến kết hợp xe thuê và boat tour nội vùng.', 'AGREED', 'Đồng ý ảnh recap nội bộ nếu có sự kiện.', 'Case v7: visitor hủy đơn sau khi đã có lịch chuẩn bị tại CT.', 'CANCELLED', CURRENT_TIMESTAMP - INTERVAL 9 DAY - INTERVAL 1 HOUR, CURRENT_TIMESTAMP - INTERVAL 9 DAY - INTERVAL 57 MINUTE, 210, CURRENT_TIMESTAMP - INTERVAL 1 DAY - INTERVAL 6 HOUR, 'Visitor tự hủy vì hội thảo chuyển sang hình thức trực tuyến.', 4, CURRENT_TIMESTAMP - INTERVAL 9 DAY - INTERVAL 1 HOUR, 210, CURRENT_TIMESTAMP - INTERVAL 1 DAY - INTERVAL 6 HOUR, 210),
